// Ten-byte AF target record per pose. Orientation Linked on, then off.
// Direct-editor getter calls stay in editorGets. Producer calls stay in producerGets.
// Imports pose.mjs unchanged. Stock image. NVRAM off. No overlay.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/record_r1.mjs om-emu
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { attachPose, POSES } from './pose.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/record_r1.mjs om-emu\n');
  process.exit(2);
}
process.env.OM_EMU_MODEL = 'E147';
process.env.OM_EMU_NVRAM = 'off';
const use = (p) => import(pathToFileURL(resolve(checkout, 'emu', p)).href);
const IMAGE_BASE = 0x60021020;
const dis = (address) => (0x50000000 + address - IMAGE_BASE) >>> 0;
const GETTER = 0x60063380;
const SETTER = 0x60063431;
const COMPLETION = 0x6006a8ca;
const REFRESH = 0x609b3c79;
const RECORD_STORE = 0x609b3d3d;
const CONVERTER = 0x609b3ecd;
const TRIPLE = 0x609b3dfb;
const CAPTURE = 0xa33f2ce0;
const CONSUMER = 0xa33ca384;
const DIRTY = 0xa33f2cea;
const OUT = resolve('work/out/record-r1.jsonl');
let DEADLINE = Date.now() + 12 * 60 * 1000;

const image = readFileSync(resolve('inputs/00_0100_50000020.decoded.bin'));
function descriptors(keys) {
  const tables = [0x60095584, 0x600b8f54, 0x600bb5ec, 0x600bda78, 0x600e4bec];
  const want = new Set(keys);
  const found = {};
  for (const start of tables) {
    let a = start;
    for (let n = 0; n < 5000 && want.size; n++) {
      const off = a - IMAGE_BASE;
      if (off < 0 || off + 4 > image.length) break;
      const key = image[off] | (image[off + 1] << 8);
      if (key === 0) break;
      const count = image[off + 2] | (image[off + 3] << 8);
      const width = (key & 3) || 4;
      if (want.has(key)) {
        found[key] = { record: a, count, width, header: image.subarray(off, off + 4).toString('hex') };
        want.delete(key);
      }
      const nxt = (a + 4 + count * width + 3) & ~3;
      if (nxt <= a) break;
      a = nxt;
    }
  }
  return found;
}
const CELL_KEYS = [0x5962, 0x88b2, 0x1dd1, 0x1db1, 0x1dc1, 0x99a1, 0x9a41, 0x99d2, 0xdfa1, 0xe91, 0x90a1, 0x84d1, 0x1df1, 0x1e01];
const desc = descriptors(CELL_KEYS);
const expectDesc = {
  0x5962: [0x600e575c, 6], 0x99a1: [0x6011ebdc, 8], 0x1dd1: [0x600e4f4c, 10],
  0x9a41: [0x6011ec34, 1], 0xe91: [0x600e4c2c, 12], 0x90a1: [0x6011e790, 2],
  0x1db1: [0x600e4f3c, 1], 0x1dc1: [0x600e4f44, 1], 0x88b2: [0x60117870, 1],
};
for (const [key, [record, count]] of Object.entries(expectDesc)) {
  const row = desc[Number(key)];
  if (!row || row.record !== record || row.count !== count) throw new Error('descriptor ' + key);
}
const WATCH = new Set([...CELL_KEYS, 0x5991, 0xe1f1]);

const { loadNand, loadImage, loadBlock, createHash: fwHash } = await use('checks/lib/env.mjs');
const { Player } = await use('src/lab/player.mjs');
const { apply_uiin_layout } = await use('src/lab/play.mjs');
const { PLAYER_PARSER } = await use('scenarios/session_replay.mjs');
const { MenuWalk } = await use('src/lab/menuwalk.mjs');
const { write_png } = await use('checks/lib/png.mjs');
const { words_to_rgb } = await use('src/lab/display.mjs');

const IMPORT_RE = /(?:from\s+|import\s*\(\s*|import\s+)['"]([^'"]+)['"]/g;
function resolveSpec(fromFile, spec) {
  if (!spec.startsWith('.')) return null;
  const base = resolve(dirname(fromFile), spec);
  for (const candidate of [base, base + '.mjs', base + '.js', join(base, 'index.mjs'), join(base, 'index.js')]) {
    if (existsSync(candidate) && statSync(candidate).isFile()) return candidate;
  }
  return null;
}
const seeds = [
  resolve(checkout, 'emu/checks/lib/env.mjs'),
  resolve(checkout, 'emu/src/lab/player.mjs'),
  resolve(checkout, 'emu/src/lab/play.mjs'),
  resolve(checkout, 'emu/scenarios/session_replay.mjs'),
  resolve(checkout, 'emu/src/lab/menuwalk.mjs'),
  resolve(checkout, 'emu/checks/lib/png.mjs'),
  resolve(checkout, 'emu/src/lab/display.mjs'),
  fileURLToPath(import.meta.url),
];
const seen = new Map();
const queue = [...seeds];
while (queue.length) {
  const file = queue.pop();
  if (!file || seen.has(file) || !existsSync(file)) continue;
  const data = readFileSync(file);
  seen.set(file, { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length });
  IMPORT_RE.lastIndex = 0;
  const text = data.toString('utf8');
  let match;
  while ((match = IMPORT_RE.exec(text))) {
    const next = resolveSpec(file, match[1]);
    if (next) queue.push(next);
  }
}
writeFileSync(resolve('work/out/record-r1-imports.json'), JSON.stringify(
  [...seen.entries()].map(([path, meta]) => ({ path: path.replaceAll('\\', '/'), sha256: meta.sha256, bytes: meta.bytes })).sort((a, b) => a.path.localeCompare(b.path)),
  null, 2,
) + '\n');

const lines = [];
const log = (row) => {
  lines.push(JSON.stringify(row));
  writeFileSync(OUT, lines.join('\n') + '\n');
  console.log(JSON.stringify({
    step: row.step, screen: row.screen, raw: row.pose && row.pose.raw, exif: row.pose && row.pose.exif,
    capture: row.capture || null, error: row.error || null,
  }));
};
const msg = (e) => String(e && e.stack ? e.stack : e).slice(0, 500);
const reasons = [];

const fw = { rom: loadImage(), resBlock: loadBlock(), summary: null, changed: [] };
apply_uiin_layout(fw.rom);
const pl = new Player(
  { ...PLAYER_PARSER, no_browser: true, idle: 'off', a15: 'on', out: '<out>', no_wait_on_error: true },
  {
    ...fw, nand: loadNand(), createHash: fwHash, wallClock: () => performance.now() / 1000,
    machine: { coverage: { mark() {}, stub() {} } }, patch: fw.summary, patchRanges: fw.changed, loaded: 'on',
  },
);
pl.camapp_components = true;
pl.camapp_native_tra = true;

let failed = null;
try {
  log({ step: 'open', descriptors: desc });
  pl.open_session();
  DEADLINE = Date.now() + 9 * 60 * 1000;
  const s = pl.session;
  const l = s.lab;
  const pose = attachPose(l);
  let phase = 'boot';
  let reading = false;
  let completion = 0;
  const gets = [];
  const sets = [];
  const entries = [];
  const tally = { refresh: 0, store: 0, converter: 0, triple: 0 };
  const callerOf = (mdr) => {
    try {
      const ra = mdr >>> 0;
      const b = l.sim.read((ra - 7) >>> 0, 7);
      if (b[0] === 0xdd) return (ra - 7) >>> 0;
      if (b[2] === 0xcd) return (ra - 5) >>> 0;
      return ra;
    } catch {
      return mdr >>> 0;
    }
  };
  l.observe(dis(GETTER), (_lab, r) => {
    if (reading) return;
    const key = r.d0 & 0xffff;
    if (!WATCH.has(key) || gets.length > 700) return;
    gets.push({ key, index: r.d1 & 0xffff, caller: callerOf(r.mdr), phase });
  }, 'obs-getter-r1');
  l.observe(dis(SETTER), (_lab, r) => {
    if (sets.length > 200) return;
    sets.push({ key: r.d0 & 0xffff, index: r.d1 & 0xffff, d2: r.d2 >>> 0, caller: callerOf(r.mdr), phase });
  }, 'obs-setter-r1');
  const watchEntry = (addr, name) => {
    l.observe(dis(addr), (_lab, r) => {
      tally[name] += 1;
      if (entries.length < 120) entries.push({ name, phase, caller: callerOf(r.mdr), d0: r.d0 & 0xffff });
    }, 'obs-' + name + '-r1');
  };
  watchEntry(REFRESH, 'refresh');
  watchEntry(RECORD_STORE, 'store');
  watchEntry(CONVERTER, 'converter');
  watchEntry(TRIPLE, 'triple');
  l.observe(dis(COMPLETION), () => { completion += 1; }, 'obs-completion-r1');

  const readKey = (key, index) => {
    reading = true;
    try { return l.call(dis(GETTER), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff; }
    finally { reading = false; }
  };
  const cells = () => {
    const out = {};
    for (const key of CELL_KEYS) {
      const n = desc[key].count;
      out[key.toString(16)] = Array.from({ length: n }, (_, i) => readKey(key, i));
    }
    return out;
  };
  const records = () => ({
    capture: [...l.sim.read(CAPTURE, 10)],
    consumer: [...l.sim.read(CONSUMER, 10)],
    dirty: l.sim.read(DIRTY, 1)[0],
  });
  const takeGets = () => {
    const out = gets.splice(0, gets.length);
    return out;
  };
  const idle = (ms) => {
    const to = l.lab_time() + ms * 1e6;
    while (l.lab_time() < to && Date.now() < DEADLINE) s.idle_slice(Math.min(to, l.lab_time() + 50e6));
  };
  const keyDown = (k, d) => { s.key(k, d); s.camapp.pump(); };
  const press = (k) => { keyDown(k, 'down'); idle(80); keyDown(k, 'up'); idle(350); };
  const dial = (n) => { s.dial_input('main', n); s.camapp.pump(); idle(400); };
  const walk = new MenuWalk({ press, frame: () => s.frame('boundary'), draws: () => l.draw_log }, { limit: 40 });
  let shotN = 0;
  const viewOf = () => {
    let screen = null;
    try { screen = s.screen(); } catch { /* not ready */ }
    try {
      const scr = walk.read();
      let highlight = null;
      for (const t of scr.texts) {
        try {
          const listed = walk.list(scr, t);
          if (listed && listed.cursor != null && listed.rows[listed.cursor]) { highlight = listed.rows[listed.cursor].text; break; }
        } catch { /* not a list */ }
      }
      return { screen, texts: scr.texts.map((t) => t.text), highlight, frame: scr.frame };
    } catch (e) {
      let frame = null;
      try { frame = s.frame('boundary'); } catch { /* none */ }
      return { screen, texts: [], highlight: null, frame, error: msg(e) };
    }
  };
  const changed = (a, b) => {
    const out = {};
    for (const k of Object.keys(a)) if (JSON.stringify(a[k]) !== JSON.stringify(b[k])) out[k] = { before: a[k], after: b[k] };
    return out;
  };
  const snap = (step, extra = {}) => {
    const view = viewOf();
    let file = null;
    if (view.frame && extra.shot !== false) {
      file = resolve('work/out/record-r1-' + String(shotN).padStart(3, '0') + '-' + step.replace(/[^a-z0-9-]+/gi, '_') + '.png');
      shotN += 1;
      write_png(file, view.frame[0], view.frame[1], words_to_rgb(view.frame[2]));
    }
    const row = {
      step, screen: view.screen, texts: view.texts, highlight: view.highlight,
      screenshot: file ? file.split(/[/\\]/).pop() : null,
      cells: extra.cells || cells(), records: extra.records || records(),
      pose: extra.pose || null, diff: extra.diff || null, note: extra.note || null,
    };
    log(row);
    return row;
  };
  const timeLeft = () => Date.now() < DEADLINE;
  const escapeShooting = () => {
    for (let i = 0; i < 8 && timeLeft(); i++) {
      if (s.screen() === 'shooting') return true;
      press('menu');
    }
    return s.screen() === 'shooting';
  };
  const openLinked = () => {
    if (s.screen() !== 'menu') press('menu');
    for (let i = 0; i < 28 && timeLeft(); i++) {
      if ((viewOf().texts || []).some((t) => t.includes('Orientation Linked'))) break;
      press('left');
    }
    for (let i = 0; i < 8 && timeLeft(); i++) {
      const cur = viewOf();
      if (cur.highlight && cur.highlight.includes('Orientation Linked')) break;
      press('down');
    }
    press('ok');
  };
  const setLinked = (wantOn) => {
    phase = 'menu';
    openLinked();
    for (let i = 0; i < 3 && timeLeft(); i++) {
      if ((viewOf().highlight || '').includes('AF Target Mode')) break;
      press('up');
    }
    const area = () => readKey(0x1db1, 0);
    const point = () => readKey(0x1dc1, 0);
    if ((area() === 1) !== wantOn) press('ok');
    press('down');
    if ((point() === 1) !== wantOn) press('ok');
    const row = snap(wantOn ? 'linked-on' : 'linked-off', { pose: pose.read() });
    escapeShooting();
    return { area: area(), point: point(), cells: row.cells };
  };
  const applyPose = (name) => {
    const compBefore = completion;
    const expect = POSES[name];
    pose.setPose(name);
    const fired = pose.deliver();
    idle(400);
    const read = pose.read();
    return { name, fired, read, completion: completion - compBefore, expect };
  };
  const checkPose = (applied) => {
    const { name, fired, read, completion: n, expect } = applied;
    if (!fired.readFired) reasons.push(name + ' register read did not fire');
    if (n < 1) reasons.push(name + ' completion not reached');
    if (read.raw !== expect.raw || read.index !== expect.index || read.exif !== expect.exif) {
      reasons.push(name + ' pose raw ' + read.raw + ' index ' + read.index + ' exif ' + read.exif);
    }
  };

  idle(400);
  phase = 'boot';
  // T3b result finding 11: Subject Detect off is 0x90a1 [1, 1]. The ROM default is 0; the live value is 1.
  const subjectOff = (v) => Array.isArray(v) && v.length === desc[0x90a1].count && v.every((n) => n === 1);
  const subject0 = cells()['90a1'];
  if (!subjectOff(subject0)) reasons.push('subject detect at boot ' + (subject0 || []).join(','));
  log({ step: 'boot-record', records: records(), subject: subject0, cells: cells() });
  const boot = applyPose('landscape');
  checkPose(boot);
  log({ step: 'boot-pose', pose: boot.read, completion: boot.completion });

  const linkedOn = setLinked(true);
  if (linkedOn.area !== 1 || linkedOn.point !== 1) reasons.push('linked on cells ' + linkedOn.area + ',' + linkedOn.point);

  const measure = (tag, name) => {
    if (!timeLeft()) { reasons.push('deadline before ' + tag + ' ' + name); return; }
    if (s.screen() !== 'shooting') escapeShooting();
    const applied = applyPose(name);
    checkPose(applied);
    phase = 'editor';
    takeGets();
    sets.length = 0;
    press('up');
    const opened = cells();
    const editorOpen = takeGets();
    snap(tag + '-' + name + '-open', { pose: applied.read, cells: opened });
    let before = opened;
    let moved = null;
    for (let d = 0; d < 5 && timeLeft(); d++) {
      press('right');
      const afterRight = cells();
      const rightDiff = changed(before, afterRight);
      if (Object.keys(rightDiff).length) {
        moved = { dials: d, key: 'right', diff: rightDiff };
        snap(tag + '-' + name + '-move', { pose: pose.read(), cells: afterRight, diff: rightDiff });
        break;
      }
      dial(1);
      before = cells();
    }
    if (!moved) {
      press('down');
      const afterDown = cells();
      const downDiff = changed(before, afterDown);
      moved = { dials: 5, key: 'down', diff: downDiff };
      snap(tag + '-' + name + '-down', { pose: pose.read(), cells: afterDown, diff: downDiff });
    }
    const editorGets = takeGets();
    const editorSets = sets.splice(0, sets.length);
    if (!moved || !Object.keys(moved.diff).length) reasons.push(tag + ' ' + name + ' move did not change a cell');
    press('menu');
    if (!escapeShooting()) reasons.push(tag + ' ' + name + ' did not return to shooting');
    phase = 's1';
    takeGets();
    const tallyBefore = { ...tally };
    const entryBefore = entries.length;
    const beforeRec = { cells: cells(), records: records() };
    keyDown('s1', 'down');
    idle(1000);
    const held = { cells: cells(), records: records(), screen: s.screen() };
    keyDown('s1', 'up');
    idle(400);
    const released = { cells: cells(), records: records(), screen: s.screen() };
    const producerGets = takeGets();
    const producerSets = sets.splice(0, sets.length);
    const entryDelta = {};
    for (const k of Object.keys(tally)) entryDelta[k] = tally[k] - tallyBefore[k];
    log({
      step: tag + '-' + name + '-s1',
      pose: applied.read,
      move: moved,
      editorGets, editorSets, editorOpen,
      producerGets, producerSets,
      producerEntries: entries.slice(entryBefore),
      entryDelta,
      before: beforeRec, held, released,
    });
    snap(tag + '-' + name + '-s1', { pose: applied.read, cells: released.cells, records: released.records, shot: true });
  };

  for (const name of ['landscape', 'exif6', 'exif8']) measure('on', name);
  const linkedOff = setLinked(false);
  if (linkedOff.area !== 0 || linkedOff.point !== 0) reasons.push('linked off cells ' + linkedOff.area + ',' + linkedOff.point);
  for (const name of ['landscape', 'exif6', 'exif8']) measure('off', name);

  const subject1 = cells()['90a1'];
  if (!subjectOff(subject1)) reasons.push('subject detect at end ' + (subject1 || []).join(','));
  const ok = reasons.length === 0 && timeLeft();
  if (!timeLeft()) reasons.push('deadline');
  log({ step: 'done', ok: reasons.length === 0, reasons, subject: subject1, counts: pose.counts });
  if (reasons.length) process.exitCode = 1;
} catch (e) {
  failed = e;
  log({ step: 'fail', ok: false, error: msg(e), reasons });
  process.exitCode = 1;
} finally {
  try { if (pl.session) pl.close_session(); } catch { /* already closed */ }
}
if (failed) process.exitCode = 1;
